class Solution {
public:
    int swimInWater(vector<vector<int>>& grid) {
        int n = grid.size();
        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> pq;
        vector<vector<bool>> visited(n, vector<bool>(n, false));
        pq.push({grid[0][0], 0, 0});
        visited[0][0] = true;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!pq.empty()) {
            auto [elevation, r, c] = pq.top();
            pq.pop();
            if (r == n - 1 && c == n - 1) return elevation;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    pq.push({max(elevation, grid[nr][nc]), nr, nc});
                }
            }
        }
        return 0;
    }
};

class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        boolean[][] visited = new boolean[n][n];
        pq.add(new int[]{grid[0][0], 0, 0});
        visited[0][0] = true;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int elevation = cur[0], r = cur[1], c = cur[2];
            if (r == n - 1 && c == n - 1) return elevation;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    pq.add(new int[]{Math.max(elevation, grid[nr][nc]), nr, nc});
                }
            }
        }
        return 0;
    }
}

var swimInWater = function(grid) {
    const n = grid.length;
    const dist = Array.from({ length: n }, () => new Array(n).fill(Infinity));
    dist[0][0] = grid[0][0];
    const q = [[grid[0][0], 0, 0]];
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (q.length > 0) {
        q.sort((a, b) => a[0] - b[0]);
        const [elevation, r, c] = q.shift();
        if (r === n - 1 && c === n - 1) return elevation;
        if (elevation > dist[r][c]) continue;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                const nextElevation = Math.max(elevation, grid[nr][nc]);
                if (nextElevation < dist[nr][nc]) {
                    dist[nr][nc] = nextElevation;
                    q.push([nextElevation, nr, nc]);
                }
            }
        }
    }
    return 0;
};
